## Feature 2: @Mentions in Candidate Notes

### 2A. DB Migration — `supabase/migrations/20260408200000_add_mentions_support.sql`

```sql
-- Add mentions column to candidate_notes
ALTER TABLE public.candidate_notes ADD COLUMN mentions uuid[] DEFAULT '{}';

-- Drop existing notification type constraint and recreate with 'mention' added
-- First check the existing constraint name by looking at the notifications table
-- The constraint is likely: notifications_type_check
ALTER TABLE public.notifications DROP CONSTRAINT IF EXISTS notifications_type_check;
ALTER TABLE public.notifications ADD CONSTRAINT notifications_type_check
  CHECK (type IN ('ranking_complete', 'ranking_failed', 'credits_low', 'credits_added', 'system',
    'stage_changed', 'note_added', 'task_assigned', 'task_completed', 'member_joined', 'mention'));

-- Trigger function to create notifications for mentioned users
CREATE OR REPLACE FUNCTION public.notify_mentions()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  mentioned_id uuid;
  job_title text;
BEGIN
  -- Skip if no mentions
  IF NEW.mentions IS NULL OR array_length(NEW.mentions, 1) IS NULL THEN
    RETURN NEW;
  END IF;

  -- Get job title for notification message
  SELECT j.title INTO job_title
  FROM public.jobs j
  WHERE j.id = NEW.job_id;

  -- Create notification for each mentioned user (excluding the note author)
  FOREACH mentioned_id IN ARRAY NEW.mentions
  LOOP
    IF mentioned_id != NEW.author_id THEN
      BEGIN
        INSERT INTO public.notifications (user_id, type, title, message, metadata)
        VALUES (
          mentioned_id,
          'mention',
          'You were mentioned in a note',
          'Someone mentioned you in a note on ' || COALESCE(job_title, 'a job'),
          jsonb_build_object('job_id', NEW.job_id, 'resume_id', NEW.resume_id, 'note_id', NEW.id)
        );
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;

CREATE TRIGGER on_note_mention
  AFTER INSERT ON public.candidate_notes
  FOR EACH ROW
  EXECUTE FUNCTION public.notify_mentions();
```

