import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// Public endpoint — allow all origins (hiring managers have no account)
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
};

function errorResponse(message: string, status: number) {
  return new Response(
    JSON.stringify({ error: message }),
    { status, headers: { ...corsHeaders, "Content-Type": "application/json" } }
  );
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "GET") {
    return errorResponse("Method not allowed", 405);
  }

  try {
    const url = new URL(req.url);
    const token = url.searchParams.get("token");

    if (!token) {
      return errorResponse("Token required", 400);
    }

    // Service role client — this endpoint is public, no user auth needed
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    // ── Validate guest link ──────────────────────────────────
    const { data: link, error: linkError } = await supabase
      .from("guest_links")
      .select("id, job_id, team_id, token, label, access_level, expires_at, revoked")
      .eq("token", token)
      .single();

    if (linkError || !link) {
      return errorResponse("Link not found", 404);
    }

    if (link.revoked) {
      return errorResponse("This link has been revoked", 403);
    }

    if (new Date(link.expires_at) < new Date()) {
      return errorResponse("This link has expired", 403);
    }

    // ── Fetch job info ────────────────────────────────────────
    const { data: job, error: jobError } = await supabase
      .from("jobs")
      .select("id, title, location, department")
      .eq("id", link.job_id)
      .single();

    if (jobError || !job) {
      return errorResponse("Job not found", 404);
    }

    // ── Fetch scored resumes (no PII — no email/phone) ───────
    const { data: resumes, error: resumeError } = await supabase
      .from("resumes")
      .select("id, candidate_name, status")
      .eq("job_id", link.job_id)
      .eq("status", "done");

    if (resumeError) {
      console.error("guest-portal: resume fetch error:", resumeError.message);
    }

    const resumeList = resumes ?? [];
    const resumeIds = resumeList.map((r: Record<string, unknown>) => r.id as string);

    // ── Fetch scores ─────────────────────────────────────────
    const { data: results } = resumeIds.length > 0
      ? await supabase
          .from("results")
          .select("resume_id, overall_score, explanation_json")
          .in("resume_id", resumeIds)
      : { data: [] };

    // ── Fetch candidate stages ────────────────────────────────
    const { data: stages } = resumeIds.length > 0
      ? await supabase
          .from("candidate_stages")
          .select("resume_id, stage")
          .in("resume_id", resumeIds)
      : { data: [] };

    // ── Merge and sanitize (NO email, NO phone, NO file paths) ─
    const resultsMap = Object.fromEntries(
      (results ?? []).map((r: Record<string, unknown>) => [r.resume_id, r])
    );
    const stagesMap = Object.fromEntries(
      (stages ?? []).map((s: Record<string, unknown>) => [s.resume_id, s.stage])
    );

    const candidates = resumeList
      .map((r: Record<string, unknown>) => {
        const rid = r.id as string;
        const result = resultsMap[rid] as Record<string, unknown> | undefined;
        const explanationJson = result?.explanation_json as Record<string, unknown> | null | undefined;
        return {
          name: (r.candidate_name as string | null) ?? "Unknown",
          score: (result?.overall_score as number | null) ?? null,
          stage: (stagesMap[rid] as string | null) ?? "new",
          summary: (explanationJson?.summary as string | null) ?? null,
        };
      })
      .sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

    return new Response(
      JSON.stringify({
        job: {
          title: job.title,
          location: (job as Record<string, unknown>).location ?? null,
          department: (job as Record<string, unknown>).department ?? null,
        },
        candidates,
        link_label: link.label ?? null,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Internal server error";
    console.error("guest-portal error:", message);
    return new Response(
      JSON.stringify({ error: "Internal server error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { useParams, Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { Skeleton } from "@/components/ui/skeleton";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { AlertCircle, Clock, Ban, Users, Trophy } from "lucide-react";
import { cn } from "@/lib/utils";

// ── Types ─────────────────────────────────────────────────────

interface PortalCandidate {
  name: string;
  score: number | null;
  stage: string;
  summary: string | null;
}

interface PortalData {
  job: {
    title: string;
    location: string | null;
    department: string | null;
  };
  candidates: PortalCandidate[];
  link_label: string | null;
}

interface PortalError {
  type: "not_found" | "revoked" | "expired" | "unknown";
  message: string;
}

// ── Stage label map ───────────────────────────────────────────

const STAGE_LABELS: Record<string, string> = {
  new: "New",
  screening: "Screening",
  interview: "Interview",
  offer: "Offer",
  hired: "Hired",
  rejected: "Rejected",
};

const STAGE_COLORS: Record<string, string> = {
  new: "bg-muted text-muted-foreground",
  screening: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  interview: "bg-violet-100 text-violet-700 dark:bg-violet-900/30 dark:text-violet-400",
  offer: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400",
  hired: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
  rejected: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
};

// ── Score color helper ────────────────────────────────────────

function scoreColor(score: number | null): string {
  if (score === null) return "bg-muted";
  if (score >= 80) return "bg-emerald-500";
  if (score >= 60) return "bg-amber-500";
  return "bg-red-500";
}

function scoreTextColor(score: number | null): string {
  if (score === null) return "text-muted-foreground";
  if (score >= 80) return "text-emerald-700 dark:text-emerald-400";
  if (score >= 60) return "text-amber-700 dark:text-amber-400";
  return "text-red-700 dark:text-red-400";
}

// ── Subcomponents ─────────────────────────────────────────────

function PortalHeader() {
  return (
    <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
      <div className="max-w-3xl mx-auto px-4 py-4 flex items-center gap-2">
        <Link
          to="/"
          className="flex items-center gap-2 text-sm font-semibold text-foreground hover:text-primary transition-colors"
        >
          <div className="w-6 h-6 rounded bg-primary flex items-center justify-center">
            <span className="text-[11px] font-bold text-primary-foreground">R</span>
          </div>
          Rankora
        </Link>
        <span className="text-muted-foreground/50 text-sm ml-1">/ Shared Candidate View</span>
      </div>
    </header>
  );
}

function PortalFooter() {
  return (
    <footer className="py-8 text-center border-t border-border mt-12">
      <p className="text-xs text-muted-foreground">
        Powered by{" "}
        <Link to="/" className="text-primary font-medium hover:text-primary/80 transition-colors">
          Rankora
        </Link>{" "}
        &mdash; AI-powered resume screening
      </p>
    </footer>
  );
}

function CandidateCard({ candidate, rank }: { candidate: PortalCandidate; rank: number }) {
  const scoreDisplay = candidate.score !== null ? Math.round(candidate.score) : null;
  const stageLabel = STAGE_LABELS[candidate.stage] ?? candidate.stage;
  const stageColor = STAGE_COLORS[candidate.stage] ?? STAGE_COLORS.new;

  return (
    <div className="rounded-xl border border-border bg-card p-4 hover:shadow-sm transition-shadow">
      <div className="flex items-start gap-3">
        {/* Rank badge */}
        <div className="flex-shrink-0 w-8 h-8 rounded-full bg-muted flex items-center justify-center text-xs font-bold text-muted-foreground">
          {rank}
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0 space-y-2">
          <div className="flex items-center justify-between gap-2 flex-wrap">
            <h3 className="text-sm font-semibold text-foreground truncate">{candidate.name}</h3>
            <div className="flex items-center gap-2 shrink-0">
              <span className={cn("text-[10px] px-2 py-0.5 rounded-full font-medium", stageColor)}>
                {stageLabel}
              </span>
              {scoreDisplay !== null && (
                <span className={cn("text-xs font-bold tabular-nums", scoreTextColor(candidate.score))}>
                  {scoreDisplay}
                </span>
              )}
            </div>
          </div>

          {/* Score progress bar */}
          {candidate.score !== null && (
            <div className="flex items-center gap-2">
              <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
                <div
                  className={cn("h-full rounded-full transition-all", scoreColor(candidate.score))}
                  style={{ width: `${Math.min(100, Math.max(0, candidate.score))}%` }}
                />
              </div>
              <span className="text-[10px] text-muted-foreground shrink-0">
                {scoreDisplay}/100
              </span>
            </div>
          )}

          {/* Summary */}
          {candidate.summary && (
            <p className="text-xs text-muted-foreground leading-relaxed line-clamp-2">
              {candidate.summary}
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

function LoadingSkeleton() {
  return (
    <div className="space-y-3">
      {[1, 2, 3, 4, 5].map((i) => (
        <div key={i} className="rounded-xl border border-border p-4 space-y-2">
          <div className="flex items-center gap-3">
            <Skeleton className="w-8 h-8 rounded-full" />
            <Skeleton className="h-4 w-40" />
            <div className="ml-auto flex items-center gap-2">
              <Skeleton className="h-5 w-16 rounded-full" />
              <Skeleton className="h-4 w-8" />
            </div>
          </div>
          <Skeleton className="h-1.5 w-full rounded-full ml-11" />
          <Skeleton className="h-3 w-3/4 ml-11" />
        </div>
      ))}
    </div>
  );
}

function ErrorState({ error }: { error: PortalError }) {
  const icons = {
    not_found: AlertCircle,
    expired: Clock,
    revoked: Ban,
    unknown: AlertCircle,
  };
  const Icon = icons[error.type];

  const hints = {
    not_found: "Double-check the URL or ask the sender to share a new link.",
    expired: "Guest links expire after 30 days. Ask the sender to generate a new one.",
    revoked: "The sender has revoked access to this link. Please reach out to them.",
    unknown: "Something went wrong loading this page. Please try again.",
  };

  return (
    <div className="text-center py-16 space-y-4 max-w-md mx-auto">
      <div className="flex justify-center">
        <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center">
          <Icon className="h-7 w-7 text-muted-foreground" />
        </div>
      </div>
      <div className="space-y-1">
        <h2 className="text-lg font-semibold">{error.message}</h2>
        <p className="text-sm text-muted-foreground">{hints[error.type]}</p>
      </div>
    </div>
  );
}

// ── Main Page ──────────────────────────────────────────────────

export default function SharedPortal() {
  const { token } = useParams<{ token: string }>();

  const { data, isLoading, error: queryError } = useQuery<PortalData, PortalError>({
    queryKey: ["guest-portal", token],
    queryFn: async () => {
      if (!token) throw { type: "not_found", message: "Invalid link" } as PortalError;

      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
      const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string;

      const res = await fetch(
        `${supabaseUrl}/functions/v1/guest-portal?token=${encodeURIComponent(token)}`,
        {
          headers: { apikey: anonKey },
        }
      );

      const json = await res.json();

      if (!res.ok) {
        const msg = (json.error as string) ?? "Failed to load";
        const type: PortalError["type"] =
          msg.toLowerCase().includes("revoked")
            ? "revoked"
            : msg.toLowerCase().includes("expired")
            ? "expired"
            : msg.toLowerCase().includes("not found")
            ? "not_found"
            : "unknown";
        throw { type, message: msg } as PortalError;
      }

      return json as PortalData;
    },
    enabled: !!token,
    retry: false,
    staleTime: 60_000,
  });

  // Derive portal error from react-query error
  const portalError: PortalError | null = queryError
    ? (queryError as PortalError)
    : null;

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <PortalHeader />

      <main className="flex-1 px-4 py-8">
        <div className="max-w-3xl mx-auto">
          {/* Loading */}
          {isLoading && (
            <div className="space-y-6">
              <div className="space-y-2">
                <Skeleton className="h-7 w-64" />
                <Skeleton className="h-4 w-40" />
              </div>
              <LoadingSkeleton />
            </div>
          )}

          {/* Error state */}
          {!isLoading && portalError && <ErrorState error={portalError} />}

          {/* Success state */}
          {!isLoading && !portalError && data && (
            <div className="space-y-6">
              {/* Job header */}
              <div className="space-y-1">
                <h1 className="text-2xl font-semibold tracking-tight text-foreground">
                  {data.job.title}
                </h1>
                <div className="flex items-center gap-3 flex-wrap">
                  {data.job.department && (
                    <span className="text-sm text-muted-foreground">{data.job.department}</span>
                  )}
                  {data.job.location && (
                    <span className="text-sm text-muted-foreground">
                      &middot; {data.job.location}
                    </span>
                  )}
                  {data.link_label && (
                    <span className="text-xs text-muted-foreground bg-muted px-2 py-0.5 rounded-full">
                      {data.link_label}
                    </span>
                  )}
                </div>
              </div>

              {/* Summary stats */}
              <div className="flex items-center gap-4 text-sm text-muted-foreground">
                <div className="flex items-center gap-1.5">
                  <Users className="h-4 w-4" />
                  <span>{data.candidates.length} candidate{data.candidates.length !== 1 ? "s" : ""}</span>
                </div>
                {data.candidates.length > 0 && data.candidates[0].score !== null && (
                  <div className="flex items-center gap-1.5">
                    <Trophy className="h-4 w-4 text-amber-500" />
                    <span>Top score: {Math.round(data.candidates[0].score)}</span>
                  </div>
                )}
              </div>

              {/* Legend */}
              <div className="flex items-center gap-3 text-xs text-muted-foreground flex-wrap">
                <span className="font-medium text-foreground">Score:</span>
                <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-emerald-500 inline-block" /> 80–100 Strong</span>
                <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-amber-500 inline-block" /> 60–79 Good</span>
                <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-red-500 inline-block" /> Below 60 Weak</span>
              </div>

              {/* Candidate list */}
              {data.candidates.length === 0 ? (
                <div className="rounded-xl border border-border bg-muted/30 py-16 text-center space-y-2">
                  <Users className="h-8 w-8 text-muted-foreground/40 mx-auto" />
                  <p className="text-sm text-muted-foreground">No scored candidates yet</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {data.candidates.map((candidate, i) => (
                    <CandidateCard key={i} candidate={candidate} rank={i + 1} />
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </main>

      <PortalFooter />
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Copy,
  Link2,
  Loader2,
  Plus,
  Trash2,
  Clock,
  CheckCircle2,
} from "lucide-react";
import { toast } from "sonner";
import { formatDistanceToNow } from "date-fns";

interface GuestLinkDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  jobId: string;
  teamId: string;
}

interface GuestLink {
  id: string;
  token: string;
  label: string | null;
  expires_at: string;
  created_at: string;
  revoked: boolean;
}

function buildShareUrl(token: string): string {
  return `${window.location.origin}/shared/${token}`;
}

export default function GuestLinkDialog({
  open,
  onOpenChange,
  jobId,
  teamId,
}: GuestLinkDialogProps) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [newLabel, setNewLabel] = useState("");
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const queryKey = ["guest-links", jobId];

  // ── Fetch existing active links ──────────────────────────────
  const { data: links = [], isLoading } = useQuery<GuestLink[]>({
    queryKey,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("guest_links")
        .select("id, token, label, expires_at, created_at, revoked")
        .eq("job_id", jobId)
        .eq("revoked", false)
        .order("created_at", { ascending: false });
      if (error) throw error;
      // Filter out already-expired links client-side
      const now = new Date();
      return (data ?? []).filter(
        (l: GuestLink) => new Date(l.expires_at) > now
      );
    },
    enabled: open && !!jobId,
    staleTime: 30_000,
  });

  // ── Generate new link ────────────────────────────────────────
  const generateLink = useMutation({
    mutationFn: async (label: string) => {
      const { data, error } = await (supabase as any)
        .from("guest_links")
        .insert({
          job_id: jobId,
          team_id: teamId,
          created_by: user?.id,
          label: label.trim() || null,
        })
        .select("id, token, label, expires_at, created_at, revoked")
        .single();
      if (error) throw error;
      return data as GuestLink;
    },
    onSuccess: (link) => {
      queryClient.invalidateQueries({ queryKey });
      const url = buildShareUrl(link.token);
      navigator.clipboard.writeText(url).catch(() => null);
      toast.success("Guest link created and copied to clipboard");
      setNewLabel("");
    },
    onError: () => {
      toast.error("Failed to create guest link");
    },
  });

  // ── Revoke a link ────────────────────────────────────────────
  const revokeLink = useMutation({
    mutationFn: async (linkId: string) => {
      const { error } = await (supabase as any)
        .from("guest_links")
        .update({ revoked: true })
        .eq("id", linkId);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Link revoked");
    },
    onError: () => {
      toast.error("Failed to revoke link");
    },
  });

  // ── Copy URL to clipboard ─────────────────────────────────────
  const handleCopy = async (link: GuestLink) => {
    const url = buildShareUrl(link.token);
    try {
      await navigator.clipboard.writeText(url);
      setCopiedId(link.id);
      toast.success("Link copied to clipboard");
      setTimeout(() => setCopiedId(null), 2000);
    } catch {
      toast.error("Failed to copy link");
    }
  };

  const handleGenerate = () => {
    if (generateLink.isPending) return;
    generateLink.mutate(newLabel);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Link2 className="h-4 w-4 text-primary" />
            Share with Hiring Manager
          </DialogTitle>
          <DialogDescription>
            Generate a read-only link so external hiring managers can view scored candidates — no login required.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 pt-1">
          {/* Existing active links */}
          <div className="space-y-2">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
              Active Links
            </p>

            {isLoading ? (
              <div className="space-y-2">
                <Skeleton className="h-14 w-full rounded-lg" />
                <Skeleton className="h-14 w-full rounded-lg" />
              </div>
            ) : links.length === 0 ? (
              <div className="rounded-lg border border-dashed border-border py-6 text-center">
                <Link2 className="h-6 w-6 text-muted-foreground/40 mx-auto mb-2" />
                <p className="text-xs text-muted-foreground">No active links yet</p>
              </div>
            ) : (
              <div className="space-y-2 max-h-48 overflow-y-auto">
                {links.map((link) => (
                  <div
                    key={link.id}
                    className="flex items-start gap-3 rounded-lg border border-border bg-muted/20 px-3 py-2.5"
                  >
                    <div className="flex-1 min-w-0 space-y-0.5">
                      <p className="text-xs font-medium text-foreground truncate">
                        {link.label ?? "Untitled link"}
                      </p>
                      <p className="text-[10px] text-muted-foreground flex items-center gap-1">
                        <Clock className="h-3 w-3 shrink-0" />
                        Expires {formatDistanceToNow(new Date(link.expires_at), { addSuffix: true })}
                      </p>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                      {/* Copy URL */}
                      <button
                        onClick={() => handleCopy(link)}
                        className="p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
                        aria-label="Copy link"
                        title="Copy link"
                      >
                        {copiedId === link.id ? (
                          <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />
                        ) : (
                          <Copy className="h-3.5 w-3.5" />
                        )}
                      </button>
                      {/* Revoke */}
                      <button
                        onClick={() => revokeLink.mutate(link.id)}
                        disabled={revokeLink.isPending}
                        className="p-1.5 rounded-md text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors"
                        aria-label="Revoke link"
                        title="Revoke link"
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Generate new link section */}
          <div className="space-y-3 border-t border-border pt-4">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
              Generate New Link
            </p>
            <div className="space-y-2">
              <Label htmlFor="guest-link-label" className="text-xs">
                Label{" "}
                <span className="font-normal text-muted-foreground">(optional)</span>
              </Label>
              <Input
                id="guest-link-label"
                placeholder="e.g., For VP Engineering"
                value={newLabel}
                onChange={(e) => setNewLabel(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") handleGenerate();
                }}
                className="h-9 text-sm"
                disabled={generateLink.isPending}
              />
            </div>
            <Button
              className="w-full gap-2"
              onClick={handleGenerate}
              disabled={generateLink.isPending}
            >
              {generateLink.isPending ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Generating…
                </>
              ) : (
                <>
                  <Plus className="h-4 w-4" />
                  Generate Link
                </>
              )}
            </Button>
            <p className="text-[10px] text-muted-foreground text-center">
              Links expire after 30 days. Viewers see candidate names, scores, and stages — no PII.
            </p>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

